proof.raw_tex:
\begin{lemma} \label{lemma:ccgits}
The number of iterations of Algorithm~\ref{alg:ccg} is bounded by
\[
\min\{n,J(M,\eps,\zeta)\},
\]
where $J=J(M,\eps,\zeta)$ is the smallest integer such that
$\sqrt{T}\tau^{J/2} \le \hat{\zeta}$ \refer{where $M$, $\hat\zeta$,
  $T$, and $\tau$ are the values returned by the algorithm}. \refer{If
  all iterates $y_i$ generated by the algorithm are stored, the number
  of matrix-vector multiplications required is bounded by
\begin{equation} \label{eq:pv8}
	\min\{n,J(M,\eps,\zeta)\}+1.
\end{equation}
If the iterates $y_i$ must be regenerated in order to define the
direction $d$ returned after \eqref{eq:weakcurvdir}, this bound
becomes $2\min\{n,J(M,\eps,\zeta)\}+1$.}
\end{lemma}

\begin{proof}
  If the full $n$ iterations are performed, without any of the
  termination conditions being tripped, the standard properties of CG
  (see Appendix~\ref{app:cgresults}) ensure that the final residual
  $r_n$ is zero, so that the condition $\|r_n \| \le \hat\zeta
  \|r_0\|$ is satisfied, and termination occurs.

  \refer{Since no more than $n$ iterations are performed, the upper
    bound $M$ is updated at most a finite number of times, so the
    quantity $J$ is well defined.}

  Supposing that $J<n$, we note from the definition of $J$ that
  $\sqrt{T}\tau^{J/2} \|r_0 \| \le \hat\zeta \|r_0\|$. Thus at least
  one of the following two conditions must be satisfied at iteration
  $J$: $\|r_{J} \| \le \hat\zeta \|r_0\|$ or $\|r_{J} \| >
  \sqrt{T}\tau^{J/2} \|r_0\|$. In either case, termination will occur
  at iteration $J$, unless it has occurred already at a previous
  iteration.

  To derive \eqref{eq:pv8}, note that the main workload at each
  iteration $j$ is computation of a single matrix-vector product
%  \refer{$H p_j$ (since matrix-vector products involving the matrices
%    $H$ and $\bH$ and the vectors $y_j$ and $r_j$ can be computed in
%    terms of this vector, in an additional $O(n)$ operations).}
%  \refer{(The ``$+1$'' in \eqref{eq:pv8} is from the additional
%    matrix-vector multiplication required in the case of $\|r_{J} \| >
%    \sqrt{T}\tau^{J/2} \|r_0\|$.)}
  \refer{$H p_j$ after the increment of $j$ (since 
    matrix-vector products involving the matrices
    $H$ and $\bH$ and the vectors $y_j$ and $r_j$ can be computed in
    terms of this vector, in an additional $O(n)$ operations).}
  \refer{(The ``$+1$'' in \eqref{eq:pv8} accounts for the initial
    matrix-vector multiplication $H p_0$ performed prior to entering 
    the loop.)}
%    \crcomment{I think the new tests based on $M$ changed the 
%    places in which we compute the $H p_j$, so I corrected this 
%    paragraph. The result still holds, but the +1 relates to the 
%    initial step (before the loop). Note that the four termination 
%    tests do not require additional matrix-vector products since $Hp_j$ 
%    has already been computed for the $M$-related tests.
%    MO: Changed account to accounts.}

  If we do not store additional information, we need to regenerate the
  information needed to compute the direction $d$ satisfying
  \eqref{eq:weakcurvdir} by re-running the iterations of CG, possibly
  up to the \refer{second-to-last} iteration. This fact accounts for
  the additional cost of $\min\{n,J(M,\eps,\zeta)\}$ in the no-storage
  case. \footnote{\refer{Interestingly, as we show in
      Appendix~\ref{app:cgresults}, the ratios on the left-hand side
      of \eqref{eq:weakcurvdir} can be calculated without knowledge of
      $y_i$ for $i=0,1,\dotsc,j-1$, provided that we store the scalar
      quantities $\alpha_i$ and $\|r_i\|^2$ for $i=0,1,\dotsc,j-1$.}}
\end{proof}

\refer{Note that $J(M,\epsilon,\zeta)$ is an increasing function of
  $M$, since $\hat{\zeta}$ is a decreasing function of $M$, while $T$
  and $\tau$ (and thus $\sqrt{T}\tau^{j/2}$) are increasing in $M$. If
  $U_H$ is known in advance, we can call Algorithm~\ref{alg:ccg} with
  $M = U_H$ and use $J(U_H,\epsilon,\zeta)$ as the bound. Alternately,
  we can call Algorithm~\ref{alg:ccg} with $M=0$ and let it adjust $M$
  as needed during the computation. Since the final value of $M$ will
  be at most $U_H$, and since $J(M,\epsilon,\zeta)$ is an increasing
  function of $M$, the quantity $J(U_H,\epsilon,\zeta)$ provides the
  upper bound on the number of iterations in this case too.}

We can estimate $J$ by taking logs in its definition, as follows:
\[
J \le \frac{2\ln(\hat{\zeta}/\sqrt{T})}{\ln(\tau)} =
\frac{\ln(\hat{\zeta}^2/T)}
     {\ln\left(\frac{\sqrt{\kappa}}{\sqrt{\kappa}+1}\right)} =
     \frac{\ln(T/\hat{\zeta}^2)}{\ln(1+{1}/{\sqrt{\kappa}})} \le
     \left(\sqrt{\kappa}+\frac{1}{2}\right)
     \ln\left(\frac{T}{\hat{\zeta}^2}\right),
\]
where we used $\ln(1+\tfrac{1}{t}) \ge \tfrac{1}{t+1/2}$ to obtain the
latest inequality. By
replacing $T,\tau,\hat{\zeta},\kappa$ by their
definitions in Algorithm~\ref{alg:ccg}, and using
$
\frac{1}{1-\sqrt{\tau}} = \frac{1+\sqrt{\tau}}{1-\tau} \le
\frac{2}{1-\tau},
$
we obtain
\begin{align} \nonumber
%% J(M,\eps,\zeta) &  \le
%% \min\left\{n,\left\lceil \left(\sqrt{\frac{M+2\eps}{\eps}}+\frac{1}{2}\right)
%% \ln\left(\frac{144 \left(\sqrt{\frac{M+2\eps}{\eps}}+1\right)^2
%%   \left(\frac{M+2\eps}{\eps}\right)^6} {\zeta^2}\right) \right\rceil \right\} \\
J(M,\eps,\zeta) &  \le
\refer{\min\left\{n,\left\lceil \left(\sqrt{\kappa}+\frac{1}{2}\right)
\ln\left(\frac{144 \left(\sqrt{\kappa}+1\right)^2
  \kappa^6} {\zeta^2}\right) \right\rceil \right\}} \\
\label{eq:HvcountcappedCG}
 & = \min \left\{ n , \tcO(\eps^{-1/2}) \right\}.
\end{align}


\begin{theorem} \label{theo:cvCGwhilestronglycvx}
Suppose that the main loop of Algorithm~\ref{alg:ccg} terminates with
$j=\hIcg$, where
\[
\hIcg \in \{1,\dotsc,\min\{n,J(M,\eps,\zeta)\}\},
\]
(where $J(M,\eps,\zeta)$ is defined in Lemma~\ref{lemma:ccgits} and
\eqref{eq:HvcountcappedCG}) \refer{because the fourth termination test is
satisfied and the three earlier conditions do not hold, that is, 
$y_{\hIcg}^\top \bH y_{\hIcg} \ge \eps \|y_{\hIcg}\|^2$, 
$p_{\hIcg}^\top \bH p_{\hIcg} \ge \eps \|p_{\hIcg}\|^2$, and
\begin{equation} \label{eq:Kitsstronglycvx}
\|r_{\hIcg}\| > \max\{\hat{\zeta},\sqrt{T}\tau^{\hIcg /2}\}\|r_0\|.
\end{equation}
where $M$, $T$, $\hat{\zeta}$, and $\tau$ are the values returned by
Algorithm~\ref{alg:ccg}. Then
$y_{\hIcg+1}$ is computed by Algorithm~\ref{alg:ccg}, and we have}
\begin{equation} \label{eq:yKp1negcurv}
\frac{(y_{\hIcg +1}-y_i)^\top \bH (y_{\hIcg+1}-y_i)}
{\|y_{\hIcg+1}-y_i\|^2} < \eps, \quad \mbox{for some $i \in \{0,\dotsc,\hIcg-1\}$.}
\end{equation}
\end{theorem}

\begin{lemma} \label{lemma:ccgsteps}
Let Assumptions~\ref{assum:compactlevelset} and~\ref{assum:fC22} hold,
and suppose that Algorithm~\ref{alg:ccg} is invoked at an iterate
$x_k$ of Algorithm~\ref{alg:dncg} (so that $\|\nabla f(x_k)\| >
\epsg>0$).
Let $d_k$ be the vector obtained in Algorithm~\ref{alg:dncg} from the
output $d$ of Algorithm~\ref{alg:ccg}. Then, one of the two following
statements holds:
\begin{enumerate}
\item {\em d\_type=SOL}, and the direction $d_k$ satisfies 
\begin{subequations} \label{eq:ccgstepSOL} 
\begin{align}
\label{eq:ccgstepSOLcurv}
d_k^\top (\nabla^2 f(x_k)+2\epsH I) d_k & \ge \epsH \|d_k\|^2, \\
\label{eq:ccgstepSOLnorm}
% \|d_k\| & \le \epsH^{-1} \sqrt{1+\zeta^2/4} \|\nabla f(x_k)\|,\\
\|d_k\| & \le \refer{1.1 \epsH^{-1} \|\nabla f(x_k)\|,}\\
\label{eq:ccgstepSOLres}
%% \|\hat{r}_k \| \le  
%% \frac{\hat{\zeta}}{1-\hat{\zeta}}(U_H+2\epsH)\|d_k\| & \le 
%% \frac{1}{2}\epsH\zeta \| d_k \|,
\|\hat{r}_k \|  & \le  \refer{\frac{1}{2}\epsH\zeta \| d_k \|,}
\end{align}
\end{subequations}
where
\begin{equation} \label{eq:def.rhat}
\hat{r}_k := (\nabla^2 f(x_k)+2\epsH I) d_k+ \nabla f(x_k);
\end{equation}
\item {\em d\_type=NC}, and the direction $d_k$ satisfies 
  $d_k^\top \nabla f(x_k) \le 0$ as well as
  \refer{
  \begin{equation} \label{eq:ccgstepNC}
    \frac{d_k^\top \nabla^2 f(x_k) d_k}{\|d_k\|^2} = -\|d_k \| \le -\epsH.
  \end{equation}
  }
%% \begin{subequations} \label{eq:ccgstepNC}
%% \begin{align}
%% \label{eq:ccgstepNCcurv}
%% \frac{d_k^\top \nabla^2 f(x_k) d_k}{\|d_k\|^2} \le -\epsH,\\
%% \label{eq:ccgstepNCnorm}
%% \|d_k\| \ge \epsH.
%% \end{align}
%% \end{subequations}
\end{enumerate}
\end{lemma}

\begin{proof}
\refer{For simplicity of notation, we use $H=\nabla^2 f(x_k)$ and
  $g=\nabla f(x_k)$ in the proof.}  Suppose first that d\_type=SOL. In
that case, we have from the termination conditions in
Algorithm~\ref{alg:ccg} and \eqref{eq:def.rhat} that
\begin{subequations} \label{eq:propSOLstep}
\begin{align} 
\label{eq:propSOLstepCURV}
d_k^\top (H+2 \epsH I)d_k & \ge \epsH \|d_k\|^2, \\
\label{eq:propSOLstepRES}
\|\hat{r}_k \| &  \le \hat{\zeta} \|g\|,
\end{align}
\end{subequations}
\refer{where $\hat\zeta$ was returned by the algorithm.}
We immediately recognize~\eqref{eq:ccgstepSOLcurv}
in~\eqref{eq:propSOLstepCURV}.  We now
prove~\eqref{eq:ccgstepSOLnorm}. Observe first 
that \eqref{eq:propSOLstepCURV} yields
\[
\epsH\|d_k\|^2 \le d_k^\top (H+2 \epsH I) d_k \le \|d_k\| \|(H+2\epsH
I) d_k\|,
\]
so from \eqref{eq:def.rhat} we have
\begin{equation*}
\|d_k\| \le \epsH^{-1} \|(H+2\epsH I)d_k\| = \epsH^{-1} \|-g+\hat{r}_k\| 
= \epsH^{-1} \sqrt{\|g\|^2 + \| \hat{r}_k \|^2} \le 
\epsH^{-1} \sqrt{1+\hat{\zeta}^2}  \|g\|,
\end{equation*}
where we used~\eqref{eq:propSOLstepRES} to obtain the final bound,
together with the equality $\|-g+\hat{r}_k\|^2=\|g\|^2+\| \hat{r}_k
\|^2$, which follows from $g^\top \hat{r}_k = r_0^\top \hat{r}_k =
0$, by orthogonality of the residuals in CG (see
Lemma~\ref{lemma:propertiesCGoneiter}, Property 2). Since
\refer{$\hat{\zeta} \le \zeta/(3 \kappa) \le 1/6$ by construction, we
  have $\|d_k \| \le \sqrt{37/36} \epsH^{-1} \|g\| \le 1.1 \epsH^{-1}
  \|g\|$, proving \eqref{eq:ccgstepSOLnorm}.}

The bound \eqref{eq:ccgstepSOLres} follows
from~\eqref{eq:propSOLstepRES} and the logic below:
\begin{align*}
	\| \hat{r}_k \| &\le \hat{\zeta} \|g\| \le 
	\hat{\zeta}\left(\|(H+2 \epsH I) d_k \| + 
	\| \hat{r}_k \|\right)  \le \hat\zeta \left( (M+2\epsH) \|d_k \| +  \| \hat{r}_k \| \right) \\
        \Rightarrow \;\; \| \hat{r}_k \| &\le 
	\frac{\hat{\zeta}}{1-\hat{\zeta}}(M+2 \epsH) \|d_k\|,
\end{align*}
\refer{where $M$ is the value returned by the algorithm.}
We finally use \refer{$\hat\zeta < 1/6$}
%% \[
%% \hat\zeta = \frac{\zeta}{3}\frac{\epsH}{M+2\epsH} \le
%% \frac{\zeta}{3} \frac12 < \frac16,
%% \]
to arrive at
\[
\frac{\hat\zeta}{1-\hat{\zeta}} (M+2\epsH) \le \frac65 \hat{\zeta}
(M+2\epsH) = \frac65 \frac{\zeta \epsH}{3} < \frac12 \zeta \epsH,
\]
yielding  \eqref{eq:ccgstepSOLres}.

In the case of d\_type=NC, we recall that Algorithm~\ref{alg:dncg}
defines
\begin{equation} \label{eq:scaleccgNC}
d_k = -\mathrm{sgn}(d^\top g) \frac{|d^\top H
  d|}{\|d\|^2} \frac{d}{\|d\|}
\end{equation}
where $d$ denotes the direction obtained by
Algorithm~\ref{alg:ccg}. It follows immediately that $d_k^\top g \le
0$. Since $d_k$ and $d$ are collinear, we also have that
\refer{
\[
\frac{d_k^\top (H+2\epsH I)d_k}{\|d_k\|^2} = \frac{d^\top (H+2\epsH
  I)d}{\|d\|^2} \le \epsH \; \Rightarrow \; \frac{d_k^\top H
  d_k}{\|d_k\|^2}
% = \frac{d^\top H d}{\|d\|^2}
\le -\epsH.
\]
By using this bound together with \eqref{eq:scaleccgNC}, we obtain
\[
\|d_k\| = \frac{|d^\top H d|}{\|d\|^2} = \frac{|d_k^\top H d_k|}{\|d_k\|^2} =
-\frac{d_k^\top H d_k}{\|d_k\|^2} \ge \epsH,
\]
proving \eqref{eq:ccgstepNC}.
}
%% establishing \eqref{eq:ccgstepNCcurv}.  By \eqref{eq:scaleccgNC}, we
%% then have
%% \[
%% \|d_k\| = \frac{|d^\top H d|}{\|d\|^2} \ge \epsH,
%% \]
%% proving \eqref{eq:ccgstepNCnorm}.
\end{proof}

\begin{lemma} \label{lemma:LSccgSOL}
Suppose that Assumptions~\ref{assum:compactlevelset}
and~\ref{assum:fC22} hold. Suppose that at iteration $k$ of
Algorithm~\ref{alg:dncg}, we have $\|\nabla f(x_k)\| > \epsg$, so
that Algorithm~\ref{alg:ccg} is called. When Algorithm~\ref{alg:ccg}
outputs a direction $d_k$ with d\_type=SOL, then the backtracking line
search requires at most $j_k \le \jsol+1$ iterations, where
\begin{equation} \label{eq:ccglsitsSOL}
\jsol \; = \; \left[ \frac{1}{2}\log_{\theta}\left(
  \frac{3(1-\zeta)}{L_H+\eta} \frac{\epsH^2}{\refer{1.1} U_g} \right)
  \right]_+,
\end{equation}
and the resulting step $x_{k+1} = x_k + \alpha_k d_k$ satisfies
\begin{equation} \label{eq:ccglsdecreaseSOL}
f(x_k) - f(x_{k+1}) \; \ge \; 
\csol\min\left(\|\nabla f(x_{k+1})\|^3 \epsH^{-3},\epsH^3\right),
\end{equation}
where 
\begin{equation*}
\csol = \frac{\eta}{6}\min\left\{ \left[ \frac{4}{\sqrt{(4+\zeta)^2+8 L_H}+4+\zeta}
  \right]^3, \left[ \frac{3\theta^2 (1-\zeta) }{L_H+\eta}
  \right]^3\right\}.
\end{equation*}
\end{lemma}

\begin{proof}
The proof tracks closely that
of~\cite[Lemma~13]{CWRoyer_SJWright_2018}. The only significant
difference is that equation (65) of~\cite{CWRoyer_SJWright_2018},
which is instrumental to the proof and requires a probabilistic
assumption on $\lambda_{\min}(\nabla^2 f(x_k))$, is now ensured
\emph{deterministically} by~\eqref{eq:ccgstepSOLnorm} from
Lemma~\ref{lemma:ccgsteps}. As a result, both the proof and the result
are deterministic.
\end{proof}

\begin{lemma} \label{lemma:LSccgNC}
  Suppose that Assumptions~\ref{assum:compactlevelset}
  and~\ref{assum:fC22} hold.  Suppose that at iteration $k$ of
  Algorithm~\ref{alg:dncg}, we have $\|\nabla f(x_k)\| > \epsg$, so
  that Algorithm~\ref{alg:ccg} is called. When Algorithm~\ref{alg:ccg}
  outputs d\_type=NC, the direction $d_k$ (computed from $d$ in
  Algorithm~\ref{alg:dncg}) has the following properties: The
  backtracking line search terminates with step length $\alpha_k =
  \theta^{j_k}$ with $j_k \le \jnc +1$, where
\begin{equation} \label{eq:eiglsits}	
\jnc := \left[ \log_{\theta}\left( \frac{3}{L_H+\eta} \right)
  \right]_+,
\end{equation}
and the resulting step $x_{k+1} = x_k + \alpha_k d_k$ satisfies
\begin{equation} \label{eq:decreaseNC}
f(x_k) - f(x_k+\alpha_k\,d_k) \; \geq \; \cnc \epsH^3,
\end{equation}	
with
\begin{equation*}
\cnc := \frac{\eta}{6}
\min\left\{1,\frac{27\theta^3}{(L_H+\eta)^3}\right\}.
\end{equation*}
\end{lemma}

\begin{proof}
  \refer{
By Lemma~\ref{lemma:ccgsteps}, we have from  \eqref{eq:ccgstepNC}
that
\begin{equation} \label{eq:boundnegcurvNCsteps}
		d_k^\top \nabla^2 f(x_k) d_k = -\|d_k\|^3 \le -\epsH \|d_k\|^2
\end{equation}
}
The result can thus be obtained exactly as in
\cite[Lemma~1]{CWRoyer_SJWright_2018}.
\end{proof}

\begin{lemma} \label{lemma:LSgeneralNC}
Suppose that Assumptions~\ref{assum:compactlevelset}
and~\ref{assum:fC22} hold.  Suppose that at iteration $k$ of
Algorithm~\ref{alg:dncg}, the search direction $d_k$ is of negative
curvature type, obtained either directly from Procedure~\ref{alg:meo}
or as the output of Algorithm~\ref{alg:ccg} and d\_type=NC. Then the
backtracking line search terminates with step length $\alpha_k =
\theta^{j_k}$ with $j_k \le \jnc +1$, where $\jnc$ is defined as in
Lemma~\ref{lemma:LSccgNC}, and the decrease in the function value
resulting from the chosen step length satisfies
\begin{equation} \label{eq:LSgeneralNCdecrease}
f(x_k) - f(x_k+\alpha_k\,d_k) \; \geq \; \frac{\cnc}{8} \epsH^3,
\end{equation}	
with $\cnc$ is defined in Lemma~\ref{lemma:LSccgNC}.
\end{lemma}

\begin{proof}
  Lemma~\ref{lemma:LSccgNC} shows that the claim holds (with a factor
  of $8$ to spare) when the direction of negative curvature is
  obtained from Algorithm~\ref{alg:ccg}.  When the direction is
  obtained from Procedure~\ref{alg:meo}, we have \refer{by the scaling
    of $d_k$ applied in Algorithm~\ref{alg:dncg} that}
\begin{equation} \label{eq:boundnegcurvNCproba}
d_k^\top \nabla^2 f(x_k) d_k = -\|d_k\|^3 \le -\frac12 \epsH \|d_k
\|^2 < 0,
\end{equation}
from which it follows that $\|d_k \| \ge \tfrac12 \epsH$. The
result can now be obtained by following the proof of
Lemma~\ref{lemma:LSccgNC}, with $\tfrac12 \epsH$ replacing $\epsH$.
\end{proof}

\begin{theorem} \label{theo:wccits}
Suppose that Assumptions~\ref{assum:compactlevelset},
\ref{assum:fC22}, and ~\ref{assum:wccmeo} hold, and define
\begin{equation} \label{eq:wccits}
\bar{K}_2 :=\left\lceil \frac{3(f(x_0)-\flow)}{\min\{\csol,\cnc/8\}}\max\{\epsg^{-3}
\epsH^3, \epsH^{-3}\} \right\rceil + 2,
\end{equation}
 where constants $\csol$ and $\cnc$
are defined in Lemmas~\ref{lemma:LSccgSOL} and~\ref{lemma:LSccgNC},
respectively.  Then with probability at least
\refer{$(1-\delta)^{\bar{K}_2}$}, Algorithm~\ref{alg:dncg} terminates
at a point satisfying \eqref{eq:2epson} in at most $\bar{K}_2$
iterations. (With probability at most
\refer{$1-(1-\delta)^{\bar{K}_2}$}, it terminates incorrectly within
$\bar{K}_2$ iterations at a point for which $\|\nabla f(x_k) \| \le
\epsg$ but $\lambda_{\min}(\nabla^2 f(x)) <
-\epsH$.)
\end{theorem}

\begin{proof}
Algorithm~\ref{alg:dncg} terminates incorrectly with probability
$\delta$ at any iteration at which Procedure~\ref{alg:meo} is called,
\refer{when Procedure~\ref{alg:meo} certifies erroneously that
  $\lambda_{\min}(\nabla^2 f(x)) \ge -\epsH$.}
%The overall probability of this happening during the first
%$\bar{K}_2$ iterations is \refer{bounded by} $\bar{K}_2
%\delta$. Therefore, with probability at least $1-\bar{K}_2 \delta$,
%no incorrect termination occurs in the first $\bar{K}_2$ iterations.
\refer{Since an erroneous certificate can only lead to termination, an
  erroneous certificate at iteration $k$ means that
  Procedure~\ref{alg:meo} did not produce an erroneous certificate at
  iterations $0$ to $k-1$. By a disjunction argument, we have that the
  overall probability of terminating with an erroneous certificate
  during the first $\bar{K}_2$ iterations is bounded by
  $1-(1-\delta)^{\bar{K}_2}$. Therefore, with probability at least
  $(1-\delta)^{\bar{K}_2} $, no incorrect termination occurs in the
  first $\bar{K}_2$ iterations.} 

Suppose now for contradiction that Algorithm~\ref{alg:dncg} runs for
$\bar{K}_2$ iterations without terminating. That is, for all 
$l=0,1,\dotsc,\bar{K}_2$, we have either $\| \nabla f(x_l) \| > \epsg$ 
or $\lambdamin(\nabla^2 f(x_l)) < -\epsH$. We perform the following 
partition of the set of iteration indices:
\begin{equation} \label{eq:K123}
  \cK_1 \cup \cK_2 \cup \cK_3 = \{0,1,\dotsc,\bar{K}_2-1\},
  \end{equation}
where $\cK_1$, $\cK_2$, and $\cK_3$ are defined as follows.

\medskip

\textbf{Case 1:} $\cK_1 := \{ l =0,1,\dotsc,\bar{K}_2-1 \, : \,
\|\nabla f(x_l) \| \le \epsg \}$.  At each iteration $l \in \cK_1$,
Algorithm~\ref{alg:dncg} calls Procedure~\ref{alg:meo}, which does not
certify that $\lambdamin (\nabla^2 f(x_l)) \ge -\epsH$ (since the
algorithm continues to iterate) but rather returns a direction of
sufficient negative curvature. By Lemma~\ref{lemma:LSgeneralNC}, the
step along this direction leads to an improvement in $f$ that is
bounded as follows:
\begin{equation} \label{eq:wccitsK1decrease}
f(x_l)-f(x_{l+1})  \ge  \frac{\cnc}{8} \epsH^3.
\end{equation}		

\medskip	

\textbf{Case 2:} $\cK_2 := \{ l=0,1,\dotsc,\bar{K}_2-1 \, : \, \|
\nabla f(x_l) \| > \epsg \; \mbox{and} \; \| \nabla f(x_{l+1}) \| >
\epsg \}$.  Algorithm~\ref{alg:dncg} calls Algorithm~\ref{alg:ccg} at
each iteration $l \in \cK_2$, returning either an approximate damped
Newton or a negative curvature direction. By combining
Lemmas~\ref{lemma:LSccgSOL} and \ref{lemma:LSccgNC}, we obtain a 
decrease in $f$ satisfying
\begin{align}
  \nonumber
f(x_l) - f(x_{l+1})  & \ge  \min\{\csol,\cnc\}
\min\left\{\| \nabla f(x_{l+1}) \|^3\epsH^{-3},\epsH^3\right\} \\
  \label{eq:wccitsK2decrease}
& \ge \min\{\csol,\cnc/8\}
\min\left\{\epsg^3\epsH^{-3},\epsH^3\right\}.
\end{align}

\medskip

\textbf{Case 3:} $\cK_3 := \{ l=0,1,\dotsc,\bar{K}_2-1 \, : \, \|
\nabla f(x_l) \| > \epsg \ge \| \nabla f(x_{l+1}) \| \}$.  Because $\|
\nabla f(x_{l+1})\|$ may be small in this case, we can no longer bound
the decrease in $f$ by an expression such as
\eqref{eq:wccitsK2decrease}. We can however guarantee at least that
$f(x_l)-f(x_{l+1}) \ge 0$. Moreover, provided that $l<\bar{K}_2-1$, we
have from $\| \nabla f(x_{l+1}) \| \le \epsg$ that the next iterate
$l+1$ is in $\cK_1$. Thus, a significant decrease in $f$ will be
attained at the {\em next} iteration, and we have
\begin{equation} \label{eq:K13}
  | \cK_3| \le |\cK_1|+1.
\end{equation}

\medskip

We now consider the total decrease in $f$ over the span of $\bar{K}_2$
iterations, which is bounded by $f(x_0)-\flow$ as follows:
\begin{align} 
  f(x_0) - \flow &\ge \sum_{l=0}^{\bar{K}_2-1} (f(x_l)-f(x_{l+1})) \nonumber \\
  \label{eq:sumdecompwccits}
& \ge \sum_{l \in \cK_1} (f(x_l)-f(x_{l+1})) +  \sum_{l \in \cK_2} (f(x_l)-f(x_{l+1})) 
\end{align}
where both sums in the final expression are nonnegative. Using first
the bound \eqref{eq:wccitsK1decrease} for the sum over $\cK_1$, we
obtain
\begin{equation} \label{eq:wccitsboundK1}
f(x_0) - \flow \; \ge \; |\cK_1| \frac{\cnc}{8} \epsH^3 \; \Leftrightarrow \; 
|\cK_1| \le \frac{f(x_0) - \flow}{\cnc/8} \epsH^{-3}.
\end{equation}
%From the sum over $\cK_2$, we obtain
%and~\eqref{eq:wccitsK2decrease} leads to
Applying~\eqref{eq:wccitsK2decrease} to the sum over $\cK_2$ leads to
\begin{equation} \label{eq:wccitsboundK2}
|\cK_2| \le \frac{f(x_0) -
  \flow}{\min\{\csol,\cnc/8\}}\max\{\epsg^{-3} \epsH^3,\epsH^{-3}\}.
\end{equation}
Using these bounds together with \eqref{eq:K13}, we have
\begin{align*}
  \bar{K}_2  & = |\cK_1| + |\cK_2| + |\cK_3| \\
  & \le  2|\cK_1|
  + |\cK_2| + 1 \\
  & \le 3\max\{|\cK_1|,|\cK_2|\} +1  \\
  & \le
\frac{3(f(x_0) - \flow)}
     {\min\{\csol,\cnc/8\}}\max\{\epsg^{-3}\epsH^3,\epsH^{-3}\} +1 \\
     & \le \bar{K}_2-1,
                \end{align*}
                giving the required contradiction.
\end{proof}

