The proof follows by combining Theorem~\ref{theo:wccits} (which bounds
the number of iterations) with Lemma~\ref{lemma:ccgits} and
Assumption~\ref{assum:wccmeo} (which bound the workload per
iteration).
  \end{proof}

\begin{lemma} \label{lemma:propertiesCGoneiter}
Suppose that $j$ iterations of the CG loop are performed in
Algorithm~\ref{alg:ccg} or~\ref{alg:cg}. Then, we have
\begin{equation} \label{eq:suffcurvuptoj}
	  \frac{p_i^\top \bH p_i}{\|p_i\|^2} > 0 \quad \mbox{for
       all $i=0,1,\dotsc,j-1$}.
\end{equation}	
Moreover, the following properties hold.
\begin{enumerate}
\item $y_i \in \lspan\left\{p_0,\dotsc,p_{i-1}\right\}$,
  $i=1,2,\dotsc,j$.
\item $r_i \in \lspan\left\{p_0,\dotsc,p_i\right\}$ for all $i=1,2,\dotsc,j$, and 
\[
r_i^\top v = 0, \quad \mbox{for all $v \in
  \lspan\left\{p_0,\dotsc,p_{i-1}\right\}$ and all $i=1,2,\dotsc,j$}.
\]
(In particular, $r_i^\top r_l = 0$ if \refer{$0 \le l<i \le j$. If} $j=n$, 
then $r_n=0$.)
\item $\|r_i\| \le \|p_i\|$, $i=0,1,\dotsc,j$.
\item $r_i^\top p_i = -\|r_i\|^2$, $i=0,1,\dotsc,j$.
\item $p_i^\top \bH p_k=0$ for all $i,k =0,1,\dotsc,j$ with $k \neq i$.
\item $p_i = -\sum_{k=0}^i ({\|r_i\|^2}/{\|r_k\|^2}) r_k$, $i=0,1,\dotsc,j$.
\item
  \[
  q(y_{i+1}) = q(y_i) - \frac{\|r_i\|^4}{2 p_i^\top \bH p_i}, \quad i=0,1,\dotsc,j-1.
  \]
\item $r_i^\top \bH r_i \ge p_i^\top \bH p_i$, $i=0,1,\dotsc,j$.
\end{enumerate}		
\end{lemma}

\begin{proof}
Since CG has not terminated prior to iteration $j$,
\eqref{eq:suffcurvuptoj} clearly holds.  All properties then follow
from the definition of the CG process, and most are proved in standard
texts (see, for example,
\cite[Chapter~5]{JNocedal_SJWright_2006}). Property 8 is less commonly
used, so we provide a proof here.

The case $i=0$ is immediate since $r_0=-p_0$ and there is
equality. When $i \ge 1$, we have:
\begin{equation*}
	p_i = -r_i + \frac{\|r_i\|^2}{\|r_{i-1}\|^2}p_{i-1} \; \Leftrightarrow \; 
	r_i = -p_i + \frac{\|r_i\|^2}{\|r_{i-1}\|^2}p_{i-1}.
\end{equation*}
(Note that if iteration $i$ is reached, we cannot have
$\|r_{i-1}\|=0$.)  It follows that
\begin{eqnarray*}
	r_i^\top \bH r_i &=   
	&p_i^\top \bH p_i -2\frac{\|r_i\|^2}{\|r_{i-1}\|^2} p_i^\top \bH p_{i-1} + 
	\frac{\|r_i\|^4}{\|r_{i-1}\|^4}p_{i-1}^\top \bH p_{i-1} \\
	&= &p_i^\top \bH p_i + \frac{\|r_i\|^4}{\|r_{i-1}\|^4}p_{i-1}^\top \bH p_{i-1},
\end{eqnarray*}
as $p_i^\top \bH p_{i-1} = 0$ by Property 5 above. Since iteration $i$
has been reached, $p_{i-1}$ is a direction of \refer{positive
  curvature},
% at least $\eps$,
and we obtain $r_i^\top \bH r_i \ge p_i^\top \bH p_i$, as required.
\end{proof}

\begin{lemma} \label{lemma:cgcurvaturescalars}
Suppose that Algorithm~\ref{alg:ccg} computes iterates up to iteration
$j+1$. Then, for any $i \in \{0,\dotsc,j\}$, we can compute
(\ref{eq:weakcurvdir}) as
\[
\frac{(y_{j+1}-y_i)^\top \bH (y_{j+1}-y_i)}{\|y_{j+1}-y_i\|^2} =
\frac{\sum_{k=i}^{j} \alpha_k \|r_k\|^2}
{\sum_{\ell=0}^j \left[\sum_{k=\max\{\ell,i\}}^j \alpha_k \|r_k\|^2 \right]^2/\|r_{\ell}\|^2}.
\]
\end{lemma}

\begin{proof}
By definition, $y_{j+1}-y_i = \sum_{k=i}^{j} \alpha_k p_k$. By
conjugacy of the $p_k$ vectors, we have
\begin{equation} \label{eq:numeratorcomp}
(y_{j+1}-y_i)^\top \bH (y_{j+1}-y_i)
= \sum_{k=i}^{j} \alpha_k^2 p_k^\top \bH p_k
= \sum_{k=i}^{j} \alpha_k \|r_k\|^2,
\end{equation}
where we used the definition of $\alpha_k$ to obtain the last
equality.  Now we turn our attention to the denominator. Using
Property 6 of Lemma~\ref{lemma:propertiesCGoneiter}, we have that
\[
y_{j+1}-y_i = \sum_{k=i}^{j} \alpha_k p_k =
\sum_{k=i}^{j} \alpha_k \left(-\sum_{\ell=0}^k \frac{\|r_k\|^2}{\|r_\ell\|^2} r_\ell \right),
\]
By rearranging the terms in the sum, we obtain
\begin{equation*}
y_{j+1}-y_i = -\sum_{k=i}^{j} \sum_{\ell=0}^k \alpha_k\|r_k\|^2 \frac{r_\ell}{\|r_{\ell}\|^2} 
= -\sum_{\ell=0}^j \left[\sum_{k=\max\{\ell,i\}}^j \alpha_k \|r_k\|^2 \right] \frac{r_\ell}{\|r_\ell\|^2}.
\end{equation*}
Using the fact that the residuals $\{ r_{\ell} \}_{\ell=0,1,\dotsc,j}$
form an orthogonal set (by Property 2 of
Lemma~\ref{lemma:propertiesCGoneiter}), we have that
\begin{equation*}
  \|y_{j+1}-y_i\|^2 = \sum_{\ell=0}^j \frac{1}{\|r_{\ell} \|^2}
  \left[\sum_{k=\max\{\ell,i\}}^j \alpha_k \|r_k\|^2 \right]^2.
\end{equation*}
Combining this with~\eqref{eq:numeratorcomp} gives the desired result.
\end{proof}

\begin{proof}
  The proof proceeds by contradiction: If we assume that all
  conditions specified in the statement of the theorem hold, and in
  addition that
\begin{equation} \label{eq:curvcondyKp1}
\frac{(y_{\hIcg +1}-y_i)^\top \bH (y_{\hIcg+1}-y_i)}
     {\|y_{\hIcg+1}-y_i\|^2} \ge \eps, \quad \mbox{for all
       $i=0,1,\dotsc,\hIcg-1$,}
\end{equation}
then we must have 
\begin{equation} \label{eq:cvCGwhilestronglycvx}
\|r_{\hIcg}\| \le \sqrt{T} \tau^{\hIcg/2} \|r_0\|,
\end{equation}
contradicting \eqref{eq:Kitsstronglycvx}. Note that
\begin{equation} \label{eq:casehK}
		\frac{(y_{\hIcg +1}-y_{\hIcg})^\top \bH (y_{\hIcg+1}-y_{\hIcg})}
		{\|y_{\hIcg+1}-y_{\hIcg}\|^2} = 
		\frac{\alpha_{\hIcg} p_{\hIcg}^\top \bH (\alpha_{\hIcg} p_{\hIcg})}
		{\|\alpha_{\hIcg} p_{\hIcg}\|^2} = \frac{p_{\hIcg}^\top \bH p_{\hIcg}}
		{\|p_{\hIcg}\|^2} \ge \eps
\end{equation}
by assumption, therefore we can consider \eqref{eq:curvcondyKp1} to
hold for $i=0,1,\dotsc,\hIcg$. Moreover, recalling the definition
\eqref{eq:quadraticCG} of the quadratic function $q$, we have for any
$i=0,1,\dotsc,\hIcg$ that 
\[
		q(y_{\hIcg+1}) = q(y_i) + \nabla q(y_i)^\top (y_{\hIcg+1}-y_i) + 
		\frac{1}{2}(y_{\hIcg+1}-y_i)^\top \bH (y_{\hIcg+1}-y_i).
                \]
Thus, \eqref{eq:curvcondyKp1} can be reformulated as
\begin{equation} \label{eq:stronglycvxyKp1yj}
% 		\forall i \in \{0,\dotsc,\hIcg\}, \quad 
		q(y_{\hIcg+1}) \ge q(y_i) + r_i^\top (y_{\hIcg+1}-y_i) 
		+ \frac{\eps}{2}\|y_{\hIcg+1}-y_i\|^2, \quad
                \mbox{for all $i=0,1,\dotsc,\hIcg$,}
\end{equation}
where we used $\nabla q(y_i)=r_i$ and the definitions
\eqref{eq:curvcondyKp1}, \eqref{eq:casehK} of strong convexity along
the directions $y_{\hIcg+1}-y_i$. In the remainder of the proof, and
similarly to \cite[Proof of Proposition
  1]{YCarmon_JCDuchi_OHinder_ASidford_2017b}, we will show that
\eqref{eq:stronglycvxyKp1yj} leads to the contradiction
\eqref{eq:cvCGwhilestronglycvx}, thus proving that
\eqref{eq:yKp1negcurv} holds.

We define the  sequence of functions $\Phi_j$, $j=0,1,\dotsc\hIcg$ as follows:
\[
    \Phi_0(z) := q(y_0) + \frac{\eps}{2}\|z-y_0\|^2,
    \]
    and for $j=0,\dotsc,\hIcg-1$:
\begin{equation} 
    \label{eq:formulaPhijplus1}
\Phi_{j+1}(z)  := \tau\Phi_j(z) + (1-\tau)\left( q(y_j) + r_j^\top
(z-y_j) +\frac{\eps}{2}\|z-y_j\|^2 \right).
\end{equation}
Since each $\Phi_j$ is a quadratic function with Hessian $\eps I$, it
can be written as follows:
\begin{equation} \label{eq:Phijwithvj}
		\Phi_j(z) \; = \; \Phi_j^* + \frac{\eps}{2}\|z-v_j\|^2,
\end{equation}
where $v_j$ is the unique minimizer of $\Phi_j$, and $\Phi_j^* =
\Phi_j(v_j)$ is the minimum value of $\Phi_j$. (Note that $v_0=y_0=0$
and $\Phi^*_0 = q(y_0) = 0$.)

Defining
\begin{equation} \label{eq:defpsi}
\psi(y) := q(y_0) - q(y) + \frac{\eps}{2}\|y-y_0\|^2 = \Phi_0(y) - q(y),
\end{equation}
we give a short inductive argument to establish that 
\begin{equation} \label{eq:PhiYJp1}
\Phi_j(y_{\hIcg+1}) \le q(y_{\hIcg+1}) + \tau^j \psi(y_{\hIcg+1}),
\quad j=0,1,\dotsc,\hIcg.
\end{equation}
For $j=0$, \eqref{eq:PhiYJp1} holds because $\Phi_0(y) = q(y) +
\psi(y)$ by definition. Assuming that \eqref{eq:PhiYJp1} holds for
some index $j \ge 0$, we find by first applying
\eqref{eq:formulaPhijplus1} (with $z=y_{\hIcg+1}$) and then
\eqref{eq:stronglycvxyKp1yj} (with $i=j$) that
\begin{eqnarray*}
\Phi_{j+1}(y_{\hIcg+1}) &= &\tau\Phi_j(y_{\hIcg+1}) + (1-\tau)\left( q(y_j) + 
r_j^\top (y_{\hIcg+1}-y_j) +\frac{\eps}{2}\|y_{\hIcg+1}-y_j\|^2 \right) \\
&\le &\tau\Phi_j(y_{\hIcg+1}) + (1-\tau) q(y_{\hIcg+1}).
\end{eqnarray*}
Thus, we have
\begin{align*}
\Phi_{j+1}(y_{\hIcg+1}) &\le \tau\Phi_j(y_{\hIcg+1}) + (1-\tau) q(y_{\hIcg+1}) \\
&\le \tau q(y_{\hIcg+1}) + \tau^{j+1} \psi(y_{\hIcg+1}) + 
(1-\tau) q(y_{\hIcg+1}) \quad \mbox{from \eqref{eq:PhiYJp1}} \\
&= q(y_{\hIcg+1}) + \tau^{j+1} \psi(y_{\hIcg+1}),
\end{align*}
which proves \eqref{eq:PhiYJp1} for $j+1$, and thus completes the
inductive argument.

We next prove another technical fact about the relationship between
$q(y_j)$ and $\Phi_j^*$, namely,
\begin{equation} \label{eq:468}
  q(y_j) \le \Phi_j^*, \quad j=0,1,\dotsc, \hIcg.
\end{equation}
We establish this result by an inductive argument that is quite
lengthy and technical; we note the termination of this phase of the
proof clearly below.


This result trivially holds (with equality) at $j=0$.  Supposing that
it holds for some $j =0,1,\dotsc, \hIcg-1$, we will prove that it also
holds for $j+1$.

By using Properties 7 and 8 of Lemma~\ref{lemma:propertiesCGoneiter},
%and also $\|\bH \| \le (M+2\eps)$, we have
\refer{and also $\|\bH r_j\| \le (M+2\eps)\|r_j\|$,} we have
\begin{equation*} 
	q(y_{j+1}) = q(y_j) - \frac{\|r_j\|^4}{2\, p_j^\top \bH p_j} \le 
	q(y_j) - \frac{\|r_j\|^4}{2\, r_j^\top \bH r_j} \le 
	q(y_j) - \frac{\|r_j\|^2}{2(M+2\eps)}.
\end{equation*}
It follows from induction hypothesis $q(y_j) \le \Phi_j^*$ that 
\begin{align} \label{eq:qyjp1Phijstar}
q(y_{j+1}) \le q(y_j) - \frac{\|r_j\|^2}{2(M+2\eps)}
&= \tau q(y_j) + (1-\tau) q(y_j) -\frac{\|r_j\|^2}{2(M+2\eps)} \nonumber \\
&\le \tau \Phi_j^* + (1-\tau) q(y_j) -\frac{\|r_j\|^2}{2(M+2\eps)}.
\end{align}
By taking the derivative in \eqref{eq:formulaPhijplus1}, and using
\eqref{eq:Phijwithvj}, we obtain
\begin{align*}
\nabla \Phi_{j+1}(z) &= \tau \nabla \Phi_j(z) + (1-\tau)\left[r_j + \eps(z-y_j)\right] \\
\Rightarrow \;\; \eps(z-v_{j+1})&=  \eps \tau (z-v_j) + (1-\tau) \left(r_j + \eps (z-y_j) \right).
\end{align*}
By rearranging the above relation (and noting  that the $z$ terms cancel out), we obtain:
\begin{equation} \label{eq:vjp1minPhijp1}
	v_{j+1}  \; = \; \tau v_j - \frac{1-\tau}{\eps}r_j + (1-\tau) y_j.
\end{equation}
It follows from this expression together with Properties 1 and 2 of
Lemma~\ref{lemma:propertiesCGoneiter} that 
\begin{equation} \label{eq:vjinKj}
v_j \in \lspan\left\{p_0,p_1,\dotsc,p_{j-1}\right\}, \quad j=1,2,\dotsc,\hIcg.
\end{equation}
(The result holds for $j=1$, from \eqref{eq:vjp1minPhijp1} we have
$v_1 \in \lspan \{v_0, r_0, y_0\} = \lspan \{r_0\} = \lspan \{p_0 \}$,
and an induction based on \eqref{eq:vjp1minPhijp1} can be used to
establish \eqref{eq:vjinKj} for the other values of $j$.)  By
combining the expressions~\eqref{eq:Phijwithvj} for $\Phi_j$,
$\Phi_{j+1}$ with the recurrence formula~\eqref{eq:formulaPhijplus1}
for $\Phi_{j+1}$, we obtain
\begin{align*} 
		\Phi_{j+1}^* + \frac{\eps}{2}\|y_j-v_{j+1}\|^2 &= \Phi_{j+1}(y_j) \\
%		&= \tau \Phi_j(y_j) + (1-\tau)\left(q(y_j)+r_j^\top (y_j-y_j) + 
%		\frac{\eps}{2}\|y_j-y_j\|^2\right)  \\
		&= \tau\Phi_j(y_j) + (1-\tau) q(y_j) \\
                &= \tau\left(\Phi_j^* + 
		\frac{\eps}{2}\|y_j-v_j\|^2\right) + (1-\tau) q(y_j)
\end{align*}
and therefore
\begin{equation} \label{eq:doubleexpressionPhijp1}
  \Phi_{j+1}^* = \tau \left(\Phi_j^* +
  \frac{\eps}{2}\|y_j-v_j\|^2\right) + (1-\tau) q(y_j) -
  \frac{\eps}{2}\|y_j-v_{j+1}\|^2.
\end{equation}
On the other hand, we have by~\eqref{eq:vjp1minPhijp1} that
\begin{eqnarray} \label{eq:normylminusvlp1}
		\|y_j-v_{j+1}\|^2 &= &\left\| \tau (y_j-v_j) 
		+\frac{1-\tau}{\eps}r_j \right\|^2 \nonumber \\
		&= &(\tau^2 \|y_j-v_j\|^2 + \frac{(1-\tau)^2}{\eps^2}\|r_j\|^2 
		+ \frac{2}{\eps}(1-\tau)\tau r_j^\top (y_j-v_j) \nonumber \\
		&= & \tau^2 \|y_j-v_j\|^2 + \frac{(1-\tau)^2}{\eps^2}\|r_j\|^2,
\end{eqnarray}
where the last relation comes from $r_j \perp
\lspan\{p_0,\dotsc,p_{j-1}\}$ (Property 2 of
Lemma~\ref{lemma:propertiesCGoneiter}) and \eqref{eq:vjinKj} in the
case $j \ge 1$, and immediately in the case $j=0$, since $y_0=v_0=0$.
By combining \eqref{eq:doubleexpressionPhijp1}
and~\eqref{eq:normylminusvlp1}, we arrive at:
\begin{align} \label{eq:phijp1star}
		\Phi_{j+1}^* &= \tau \left(\Phi_j^* + 
		\frac{\eps}{2}\|y_j-v_j\|^2\right) + (1-\tau) q(y_j) 
		- \frac{\eps}{2}\|y_j-v_{j+1}\|^2 \nonumber \\
		&= \tau \left(\Phi_j^* + 
		\frac{\eps}{2}\|y_j-v_j\|^2\right) + (1-\tau) q(y_j) 
		-\frac{\eps}{2}\tau^2 \|y_j-v_j\|^2 - \frac{(1-\tau)^2}{2\eps} \|r_j\|^2 
		\nonumber \\
		&= \tau \Phi_j^* + \frac{\eps}{2}\left[ \tau 
		-\tau^2\right]\|y_j-v_j\|^2 + (1-\tau) q(y_j) 
		- \frac{(1-\tau)^2}{2\eps} \|r_j\|^2 \nonumber \\ 
		&= \tau \Phi_j^* + 
		\frac{\eps}{2}(1-\tau)\tau \|y_j-v_j\|^2 + (1-\tau) q(y_j) 
		- \frac{(1-\tau)^2}{2\eps} \|r_j\|^2 \nonumber \\
		&\ge \tau \Phi_j^* + (1-\tau) q(y_j) 
		- \frac{(1-\tau)^2}{2\eps} \|r_j\|^2 \nonumber \\
                &\ge q(y_{j+1}) + \frac{1}{2(M+2\eps)}\|r_j\|^2 
		- \frac{(1-\tau)^2}{2\eps} \|r_j\|^2.
\end{align}
where the last inequality comes from~\eqref{eq:qyjp1Phijstar}.  By
using the definitions of $\tau$ and $\kappa$ in
Algorithm~\ref{alg:ccg}, we have
\[
		\frac{(1-\tau)^2}{2\eps} = \frac{1}{2\eps(\sqrt{\kappa}+1)^2} \le 
		\frac{1}{2\eps\kappa} = \frac{1}{2(M+2\eps)}.
\]
It therefore follows from \eqref{eq:phijp1star} that $q(y_{j+1}) \le
\Phi_{j+1}^*$. At this point, we have shown that when $q(y_j) \le
\Phi_j^*$ for $j=0,1,\dotsc,\hIcg-1$, it follows that $q(y_{j+1}) \le
\Phi_{j+1}^*$, establishing the inductive step. As a result, our
proof of \eqref{eq:468} is complete.


By substituting $j=\hIcg$ into \eqref{eq:468}, we obtain
$q(y_{\hIcg}) \le \Phi_{\hIcg}^*$,
which in combination with \eqref{eq:PhiYJp1} with $j=\hIcg$, and the
definition \eqref{eq:Phijwithvj}, yields
\begin{equation} \label{eq:desiredecreaseformula}
q(y_{\hIcg}) -q(y_{\hIcg+1}) \le \Phi_{\hIcg}^* - q(y_{\hIcg+1}) 
\le \Phi_{\hIcg}(y_{\hIcg+1}) - q(y_{\hIcg+1})
\le \tau^{\hIcg} \psi(y_{\hIcg+1}).
\end{equation}
By substitution from \eqref{eq:defpsi}, we obtain
\begin{equation} \label{eq:funcdecreasecontrad}
q(y_{\hIcg}) - q(y_{\hIcg+1}) \; \le \; \tau^{\hIcg}
\left(q(y_0)-q(y_{\hIcg+1}) +
\frac{\eps}{2}\|y_0-y_{\hIcg+1}\|^2\right).
\end{equation}

We now depart from the analysis
of~\cite{YCarmon_JCDuchi_OHinder_ASidford_2017b}, and complete the
proof of this result by expressing \eqref{eq:funcdecreasecontrad} in
terms of residual norms.  On the left-hand side, we have
\begin{align*}
  q(y_{\hIcg}) - q(y_{\hIcg+1})
  % &= &\nabla q(y_{\hIcg+1})^\top (y_{\hIcg}-y_{\hIcg+1}) + 
%		\frac{1}{2}(y_{\hIcg}-y_{\hIcg+1})^\top \bH (y_{\hIcg}-y_{\hIcg+1})  \\ 
		&= r_{\hIcg+1}^\top (y_{\hIcg}-y_{\hIcg+1}) + 
		\frac{1}{2}(y_{\hIcg}-y_{\hIcg+1})^\top \bH (y_{\hIcg}-y_{\hIcg+1})  \\
		&= \frac{1}{2}(y_{\hIcg}-y_{\hIcg+1})^\top \bH (y_{\hIcg}-y_{\hIcg+1})
\end{align*}
because $r_{\hIcg+1}^\top (y_{\hIcg}-y_{\hIcg+1}) = r_{\hIcg+1}^\top
(\alpha_{\hIcg} p_{\hIcg}) = 0$ by
Lemma~\ref{lemma:propertiesCGoneiter}, Property 2.
We thus have from \eqref{eq:casehK} that
\begin{alignat}{2}
  \nonumber
  q(y_{\hIcg}) - q(y_{\hIcg+1}) &\ge \frac{\eps}{2}\|y_{\hIcg}-y_{\hIcg+1}\|^2  &&  \\
  \nonumber
  &\refer{= \frac{\eps}{2} \|\alpha_{\hIcg}p_{\hIcg}\|^2} \\
  \nonumber
  &\refer{\ge \frac{\eps}{2 (M+2\eps)^2}\|\bH(\alpha_{\hIcg}p_{\hIcg})\|^2} 
  && \mbox{(since $\|\bH p_{\hIcg}\| \le (M+2\eps)\|p_{\hIcg}\|$)} \\
  \nonumber
%  &\ge \frac{\eps}{2 (M+2\eps)^2} \|\bH(y_{\hIcg}-y_{\hIcg+1})\|^2  && \mbox{(since $\bH \preceq (M+2\eps)I$)} \\
  &= \frac{\eps}{2 (M+2\eps)^2} \|\bH(y_{\hIcg}-y_{\hIcg+1})\|^2   \\
  \nonumber
  &= \frac{\eps}{2 (M+2\eps)^2} \|r_{\hIcg} - r_{\hIcg+1}\|^2  && \mbox{(since $r_j=g+\bH y_j$)} \\
  \nonumber
		&= \frac{\eps}{2 (M+2\eps)^2} (\|r_{\hIcg}\|^2 + \|r_{\hIcg+1}\|^2) & \quad & \mbox{(by Lemma~\ref{lemma:propertiesCGoneiter}, Property 2)} \\
  \label{eq:funcdeccontradLHS}
		& \ge \frac{\eps}{2 (M+2\eps)^2} \|r_{\hIcg}\|^2,
\end{alignat}


On the right-hand side of~\eqref{eq:funcdecreasecontrad}, because of
the strong convexity condition \eqref{eq:stronglycvxyKp1yj} at $i=0$,
we have
\begin{align*}
q(y_0)-q(y_{\hIcg+1}) + \frac{\eps}{2}\|y_0-y_{\hIcg+1}\|^2  & \le 
-\nabla q(y_0)^\top (y_{\hIcg+1}-y_0) \\
&= -r_0^\top (y_{\hIcg+1}-y_0)  \le \|r_0\|\|y_{\hIcg+1}-y_0\|.
\end{align*}
Moreover, we have 
\[
		\|y_{\hIcg+1}-y_0\| \; = \;
		\left\|\sum_{i=0}^{\hIcg} \alpha_i p_i \right\| 
		\; \le \; \sum_{i=0}^{\hIcg} \alpha_i \|p_i\| 
		\; = \; \sum_{i=0}^{\hIcg} \frac{\|r_i\|^2}{p_i^\top \bH p_i}\|p_i\|,
\]
where the last relation follows from the definition of $\alpha_i$. By
combining these last two bounds, and using Property 3 of
Lemma~\ref{lemma:propertiesCGoneiter}, we obtain
\begin{equation} \label{eq:wd12}
		q(y_0)-q(y_{\hIcg+1}) + \frac{\eps}{2}\|y_0-y_{\hIcg+1}\|^2 \; \le \; 
		\|r_0\| \sum_{i=0}^{\hIcg} \|r_i\| \frac{\|p_i\|^2}{p_i^\top \bH p_i} \;
		\le \; \|r_0\| \frac{1}{\eps} \sum_{i=0}^{\hIcg} \|r_i\|,
\end{equation}
where the last inequality holds $p_j^\top \bH p_j \ge \eps \|p_j\|^2$
for $j=0,1,\dotsc,\hIcg$ by assumption.

To bound the sum in \eqref{eq:wd12}, we recall that since
Algorithm~\ref{alg:ccg} did not terminate until iteration $\hIcg$,
\refer{the residual norms $\|r_i \|$ at all iterations
  $i=0,1,\dotsc,\hIcg-1$ must have decreased at the expected
  convergence rate. In particularly, we have $\|r_i\| \le \sqrt{T}
  \tau^{i/2} \|r_0\|$ for the {\em possibly smaller} versions of
  $\sqrt{T}$ and $\tau$ that prevailed at iteration $i$, so certainly
  $\|r_i\| \le \sqrt{T} \tau^{i/2} \|r_0\|$ for the final values of
  these parameters.} Thus for $i=0,1,\dotsc,\hIcg-1$, we have
\[
\|r_i\| \le \sqrt{T} \tau^{i/2} \|r_0\| \le \tau^{(i-\hIcg)/2}\|r_{\hIcg}\|,
\]
where we used $\|r_{\hIcg}\| \ge \sqrt{T} \tau^{\hIcg/2} \|r_0\|$
(from \eqref{eq:Kitsstronglycvx}) for the last inequality. Observing
that this bound also holds (trivially) for $i=\hIcg$, we obtain by
substituting in \eqref{eq:wd12} that
\begin{align}
  \nonumber
q(y_0)-q(y_{\hIcg+1}) + \frac{\eps}{2}\|y_0-y_{\hIcg+1}\|^2
&\le \|r_0\| \frac{1}{\eps} \sum_{i=0}^{\hIcg} \tau^{(i-\hIcg)/2} \|r_{\hIcg}\| \\
\nonumber
&\le \|r_0\| \frac{\tau^{-\hIcg/2}}{\eps}\|r_{\hIcg}\|\,\sum_{i=0}^{\hIcg} (\sqrt{\tau})^{i} \\
\label{eq:funcdeccontradRHS}
& \le \|r_0\| \frac{\tau^{-\hIcg/2}}{\eps}\|r_{\hIcg}\| \frac{1}{1-\sqrt{\tau}}.
\end{align}
Applying successively \eqref{eq:funcdeccontradLHS},
\eqref{eq:funcdecreasecontrad} and \eqref{eq:funcdeccontradRHS}
finally yields:
\begin{align*}
		\frac{\eps}{2 (M+2\eps)^2} \|r_{\hIcg}\|^2 &\le 
		 q(y_{\hIcg}) - q(y_{\hIcg+1}) \\
		 &\le \tau^{\hIcg} \left( q(y_0)-q(y_{\hIcg+1}) + \frac{\eps}{2}\|y_0-y_{\hIcg+1}\|^2 \right) \\
		 &\le \tau^{\hIcg} \|r_0\|\|r_{\hIcg}\| 
		 \frac{\tau^{-\hIcg/2}}{\eps}\frac{1}{1-\sqrt{\tau}}.
\end{align*}
After rearranging this inequality and dividing by $\|r_{\hIcg}\| > 0$,
we obtain
\begin{equation} \label{eq:finalcontrad}
		\|r_{\hIcg}\| \le \frac{2 (M+2\eps)^2}{\eps^2}\frac{\tau^{\hIcg/2}}{1-\sqrt{\tau}} \|r_0\|
		= \sqrt{T} \tau^{\hIcg/2}\|r_0\|.
\end{equation}
We have thus established \eqref{eq:cvCGwhilestronglycvx} which, as we
noted earlier, contradicts \eqref{eq:Kitsstronglycvx}. Thus
\eqref{eq:curvcondyKp1} cannot be true, so we have established
\eqref{eq:yKp1negcurv}, as required.
\end{proof}

