We consider the unconstrained optimization problem
\begin{equation} \label{eq:f}
\min_{x \in \R^n} \, f(x),
\end{equation}

Our algorithm seeks a point that approximately satisfies second-order
necessary conditions for optimality, that is,
\begin{equation}\label{eq:2epson}
\| \nabla f (x)\| \le \epsg, \quad \lambda_{\min}(\nabla^2 f(x)) \ge
-\epsH,
\end{equation}

\begin{assumption} \label{assum:compactlevelset}
The level set $\mathcal{L}_f(x_0) = \{x | f(x) \le f(x_0)\}$ is
compact.
\end{assumption}

\begin{assumption} \label{assum:fC22}
The function $f$ is twice uniformly Lipschitz continuously
differentiable on an open neighborhood of $\mathcal{L}_f(x_0)$
\refer{that includes the trial points generated by the algorithm. We
  denote by $L_H$ the Lipschitz constant for $\nabla^2 f$ on this
  neighborhood}.
%% \crcomment{Removed $L_g$ because it is not used anywhere else in
%% the paper and we already have multiple notations for Hessian norms
%% or their approximations. We only need Lipschitz continuous
%% Hessians, and bounded gradients/Hessians (the latter implying that
%% the gradient is Lipschitz continuous).}
%\sjwcomment{I made changes. OK now? CR: Ok.}
\end{assumption}

For any $x$ and $d$ such that Assumption~\ref{assum:fC22} is satisfied at $x$ 
and $x+d$, we have
\begin{equation} \label{eq:LH}
f(x+d) \le f(x) + \nabla f(x)^\top d + \frac12 d^\top \nabla^2 f(x) d
+ \frac{L_H}{6} \| d\|^3.
\end{equation}

\begin{algorithm}[ht!]
\caption{Capped Conjugate Gradient}
\label{alg:ccg}
\begin{algorithmic}
\STATE \emph{Inputs:} Symmetric matrix $H \in \R^{n \times n}$; 
vector $g \ne 0$; damping parameter $\epsilon \in (0,1)$; desired relative 
accuracy \refer{$\zeta \in (0,1)$};
\STATE \refer{\emph{Optional input:} scalar $M$ (set to $0$ if not provided)};
\STATE \refer{\emph{Outputs:} d\_type, $d$;}
\STATE \refer{\emph{Secondary outputs:} final values of $M$, $\kappa$, 
$\hat{\zeta}$, $\tau$, and $T$;}
\STATE Set
\[
\bH:=H+2\eps I, \quad \kappa := \frac{M+2\eps}{\eps}, \quad \hat{\zeta} := \frac{\zeta}{3 \kappa},
\quad
\tau := \frac{\sqrt{\kappa}}{\sqrt{\kappa}+1}, \quad
T:=\frac{4\kappa^4}{(1-\sqrt{\tau})^2};
\]
\STATE $y_0 \leftarrow 0$, $r_0 \leftarrow g$, $p_0 \leftarrow -g$, $j \leftarrow 0$; 
\IF{$p_0^\top \bH p_0 < \eps \|p_0\|^2$}
\STATE Set $d=p_0$ and terminate with d\_type=NC;
\ELSIF{\refer{$\|H p_0\| > M \|p_0\|$}}
\STATE \refer{Set $M \leftarrow {\|H p_0\|}/{\|p_0\|}$ 
and update $\kappa,\hat{\zeta},\tau,T$ accordingly;}
\ENDIF
\WHILE{TRUE}
\STATE $\alpha_j \leftarrow {r_j^\top r_j}/{p_j^\top \bH p_j}$;
\COMMENT{Begin Standard CG Operations}
\STATE $y_{j+1} \leftarrow y_j+\alpha_j p_j$;
\STATE $r_{j+1} \leftarrow r_j + \alpha_j \bH p_j$;
\STATE $\beta_{j+1} \leftarrow {(r_{j+1}^\top r_{j+1})}/{(r_j^\top r_j)}$;
\STATE $p_{j+1} \leftarrow  -r_{j+1} + \beta_{j+1}p_j$;
\COMMENT{End Standard CG Operations}
\STATE $j \leftarrow  j+1$;
\IF{\refer{$\|H p_j\| > M \|p_j\|$}}
\STATE \refer{Set $M \leftarrow {\|H p_j\|}/{\|p_j\|}$ 
and update $\kappa,\hat{\zeta},\tau,T$ accordingly;}
\ENDIF
\IF{\refer{$\|H y_j\| > M \|y_j\|$}}
\STATE \refer{Set $M \leftarrow {\|H y_j\|}/{\|y_j\|}$ 
and update $\kappa,\hat{\zeta},\tau,T$ accordingly;}
\ENDIF
\IF{\refer{$\| H r_j\| > M \|r_j\|$}}
\STATE \refer{Set $M  \leftarrow {\| H r_j\|}/{\|r_j\|}$ 
and update $\kappa,\hat{\zeta},\tau,T$ accordingly;}
\ENDIF
\IF{$y_j^\top \bH y_j < \epsilon \|y_j\|^2$}
\STATE Set $d \leftarrow y_j$ and terminate with d\_type=NC;
%\ELSIF{$\| r_j \| \le \tfrac{1}{2}\min\{\zeta\|r_0\|,\eps \|y_j\|\}$}
\ELSIF{$\| r_j \| \le \hat{\zeta} \|r_0\|$}
\STATE Set $d \leftarrow y_j$ and terminate with d\_type=SOL;
\ELSIF{$p_j^\top \bH p_j < \eps \|p_j\|^2$}
\STATE Set $d \leftarrow p_j$ and terminate with d\_type=NC;
\ELSIF{$\|r_j\| >  \sqrt{T}\tau^{j/2} \|r_0\|$
%\crnote{The key here is 
%that when we terminate because of this condition, we are sure that 
%$\|H v\| \le (M+2\eps)\|v\|$ for $v\in \{p_0,\dots,p_j,y_0,\dots,y_j,r_0,\dots,r_j\}$ 
%and this is all we need. As long as the residual norm decreases at the 
%desired rate, things are okay because $\sqrt{T}\tau^{j/2}$ is an 
%increasing function of $M$.}
}
\STATE Compute $\alpha_j,y_{j+1}$ as in the main loop above;
\STATE Find $i \in \{0,\dotsc,j-1\}$ such that
\begin{equation} \label{eq:weakcurvdir}
	\frac{(y_{j+1}-y_i)^\top \bH (y_{j+1}-y_i)}{\|y_{j+1}-y_i\|^2} \; < \; \eps;
\end{equation}
\STATE Set $d \leftarrow y_{j+1}-y_i$ and terminate with d\_type=NC;
\ENDIF
\ENDWHILE
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[ht!]
\caption{Minimum Eigenvalue Oracle}
\label{alg:meo}
\begin{algorithmic}
%  \STATE \emph{Inputs:} Symmetric matrix $H \in \R^{n \times n}$,
%  scalar $M$ such that $\lambdamax(H) \le M$, and $\epsilon>0$;
%  \STATE Set parameter $\delta \in [0,1)$;
  \STATE \emph{Inputs:} Symmetric matrix $H \in \R^{n \times n}$,
  \refer{tolerance $\epsilon>0$};
  \STATE \refer{\emph{Optional input:} Upper bound on Hessian norm 
  $M$;}
  \STATE \emph{Outputs:} An estimate $\lambda$ of $\lambdamin(H)$
  such that $\lambda \le - \epsilon/2$, and vector $v$
  with $\|v\|=1$ such that $v^\top H v =\lambda$ OR
  a certificate that $\lambdamin(H) \ge -\epsilon$. In the latter case, when
  the certificate is output, it is false with probability $\delta$ 
  \refer{for some $\delta \in [0,1)$}.
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[ht!]
\caption{Damped Newton-CG}
\label{alg:dncg}
\begin{algorithmic}
\STATE \emph{Inputs:} Tolerances  $\epsg>0$, $\epsH>0$; backtracking 
parameter $\theta \in (0,1)$; starting point $x_0$; 
\refer{accuracy parameter $\zeta \in (0,1)$;}
\STATE \refer{\emph{Optional input:} Upper bound  $M > 0$ on Hessian 
norm};
%\STATE \refer{\emph{Optional input:} Upper bound  $U_H > 0$ on Hessian 
%norm}; 
\FOR{$k=0,1,2,\dotsc$}
\IF{$\|\nabla f(x_k)\| > \epsg$}
\STATE Call Algorithm~\ref{alg:ccg} with $H = \nabla^2 f(x_k)$, $\epsilon=\epsH$, 
$g=\nabla f(x_k)$, accuracy parameter $\zeta$ and $M$ if provided, 
to obtain outputs $d$, d\_type; 
\IF{d\_type=NC}
\STATE $d_k \leftarrow -\mathrm{sgn}(d^\top g) \frac{|d^\top \nabla^2 f(x_k) d|}{\|d\|^2} 
\frac{d}{\|d\|}$;
\ELSE[\refer{d\_type=SOL}]
\STATE $d_k \leftarrow d$;
\ENDIF
\STATE Go to \textbf{Line Search};
\ELSE
\STATE Call Procedure~\ref{alg:meo} with $H = \nabla^2 f(x_k)$,
$\epsilon=\epsH$ and $M$ if provided; 
\IF{Procedure~\ref{alg:meo} certifies that $\lambdamin(\nabla^2 f(x_k)) \ge -\epsH$}
\STATE
Terminate; 
\ELSE[\refer{direction of sufficient negative curvature found}]
\STATE 
$d_k \leftarrow -\mathrm{sgn}(v^\top g) \frac{|v^\top \nabla^2 f(x_k) v|}{\|v\|^2} v$
% \sjwnote{Holy smokes, the last $v$ was missing from this formula!}
(where $v$ is the output from Procedure~\ref{alg:meo})
and go to \textbf{Line Search};
\ENDIF
\ENDIF
\STATE \textbf{Line Search}: Compute a step length $\alpha_k=\theta^{j_k}$, 
where $j_k$ is the smallest nonnegative integer such that
\begin{equation} \label{eq:lsdecreasedamped}
	f(x_k + \alpha_k d_k) < f(x_k) - \frac{\eta}{6}\alpha_k^3 \|d_k\|^{3};
\end{equation}
\STATE $x_{k+1} \leftarrow x_k+\alpha_k d_k$;
\ENDFOR
\end{algorithmic}
\end{algorithm}

\begin{assumption} \label{assum:wccmeo}
For every iteration $k$ at which Algorithm~\ref{alg:dncg} calls
Procedure~\ref{alg:meo}, and for a specified failure probability
$\delta$ with $0 \le \delta \ll 1$, Procedure~\ref{alg:meo} either
certifies that $\nabla^2 f(x_k) \succeq -\epsH I$ or finds a vector
of curvature smaller than $-{\epsH}/{2}$ in at most
%% \crcomment{Changed the value to reflect our new bounds on the
%% number of iterations.}
\begin{equation} \label{eq:wccmeo}
		N_{\mathrm{meo}}:=\min\left\{n,
		1+\left\lceil\Cmeo\epsH^{-1/2}\right\rceil\right\}
\end{equation}
Hessian-vector products, \refer{with probability $1-\delta$,} where
$\Cmeo$ depends at most logarithmically on $\delta$ and $\epsH$.
%\sjwcomment{I changed some more. Is this OK? CR: Yes.}
%% \crcomment{Modified the last part of the assumption to cope with 
%% the discussion before Corollary~\ref{coro:wcc2Hv}, where $\Cmeo$ depends 
%% on $\epsH$ through $\delta$. That also avoids mentioning this logarithmic 
%% dependency in the statement of the corollary.}
\end{assumption}

\begin{algorithm}[ht!]
\caption{Conjugate Gradient}
\label{alg:cg}
\begin{algorithmic}
  \STATE \emph{Inputs:} Symmetric matrix $\bH$, vector $g$;
  \STATE $r_0 \leftarrow g$, $p_0 \leftarrow -r_0$, $y_0 \leftarrow 0$, $j \leftarrow 0$;
  \WHILE{$p_j^\top\bH p_j>0$ and $r_j \ne 0$}
  \STATE $\alpha_j \leftarrow {r_j^\top r_j}/{p_j^\top \bH p_j}$;
\STATE $y_{j+1} \leftarrow y_j+\alpha_j p_j$;
\STATE $r_{j+1} \leftarrow r_j + \alpha_j \bH p_j$;
\STATE $\beta_{j+1} \leftarrow {(r_{j+1}^\top r_{j+1})}/{(r_j^\top r_j)}$;
\STATE $p_{j+1} \leftarrow -r_{j+1} + \beta_{j+1}p_j$;
\STATE $j \leftarrow j+1$;
\ENDWHILE
\end{algorithmic}
\end{algorithm}

Here and below, we refer often to the following quadratic function:
\begin{equation} \label{eq:quadraticCG}
	q(y) := \frac{1}{2}y^\top \bH y + g^\top y,
\end{equation}

\begin{proof}
The proof follows by combining Theorem~\ref{theo:wccits} (which bounds
the number of iterations) with Lemma~\ref{lemma:ccgits} and
Assumption~\ref{assum:wccmeo} (which bound the workload per
iteration).
  \end{proof}

\begin{proof}
The proof follows by combining Theorem~\ref{theo:wccits} (which bounds
the number of iterations) with Lemma~\ref{lemma:ccgits} and
Assumption~\ref{assum:wccmeo} (which bound the workload per
